+import { injectForPathFromDisk } from "../core/inject.ts";
+
+// Example integration for tools/agents without pre-tool-use hook support.
+// This shows how a standalone tool can inject records without needing a plugin.
+
+export const getRecordsForFile = (
+  repoRoot: string,
+  filePath: string,
+): string | null => {
+  // For any tool or agent, just call this function when a file is opened/read
+  return injectForPathFromDisk(repoRoot, filePath);
+};
+
+// Example: CLI tool that prints records for a given file
+export const printRecordsForFile = (repoRoot: string, filePath: string): void => {
+  const records = getRecordsForFile(repoRoot, filePath);
+  if (records) {
+    console.log(`=== Records for ${filePath} ===`);
+    console.log(records);
+  } else {
+    console.log(`No records found for ${filePath}`);
+  }
+};
