@@ -0,0 +1,33 @@
+import { existsSync, readFileSync } from "fs";
+import { join } from "path";
+import type { Record } from "./project.ts";
+
+const STORE_DIR = ".commitlore/records";
+
+const recordPathForFile = (repoRoot: string, filePath: string): string => {
+  return join(repoRoot, STORE_DIR, `${filePath}.records`);
+};
+
+export const readRecordsFromDisk = (
+  repoRoot: string,
+  filePath: string,
+): readonly Record[] => {
+  const recordPath = recordPathForFile(repoRoot, filePath);
+
+  if (!existsSync(recordPath)) {
+    return [];
+  }
+
+  try {
+    const content = readFileSync(recordPath, "utf-8");
+    const lines = content.split("\n").filter((line) => line.trim());
+
+    return lines.map((line, idx) => ({
+      id: `disk-${filePath}-${idx}`,
+      filePath,
+      content: line,
+    }));
+  } catch {
+    return [];
+  }
+};
