+import { mkdirSync, writeFileSync } from "fs";
+import { dirname, join } from "path";
+import type { Record } from "./project.ts";
+
+const STORE_DIR = ".commitlore/records";
+
+export const writeRecordsToDisk = (
+  repoRoot: string,
+  records: readonly Record[],
+): void => {
+  // Group records by file path
+  const byPath = new Map<string, Record[]>();
+
+  for (const record of records) {
+    if (!byPath.has(record.filePath)) {
+      byPath.set(record.filePath, []);
+    }
+    byPath.get(record.filePath)!.push(record);
+  }
+
+  // Write each file's records to disk
+  for (const [filePath, fileRecords] of byPath.entries()) {
+    const recordPath = join(repoRoot, STORE_DIR, `${filePath}.records`);
+    const dir = dirname(recordPath);
+
+    mkdirSync(dir, { recursive: true });
+
+    const content = fileRecords.map((r) => r.content).join("\n");
+    writeFileSync(recordPath, content, "utf-8");
+  }
+};
