+import { recordsForPath, readRecordsForPathFromDisk } from "./query.ts";

+// For editors WITH pre-tool-use hooks (called on-demand when a file is accessed).
 export const injectForPath = (repo: string, filePath: string): string | null => {
   const records = recordsForPath(repo, filePath);
   if (records.length === 0) return null;
   return project(records);
 };
+
+// For editors WITHOUT hooks (reads from disk — can be called by any tool/editor).
+// This is the fallback path that works in any environment without plugin support.
+export const injectForPathFromDisk = (
+  repoRoot: string,
+  filePath: string,
+): string | null => {
+  const records = readRecordsForPathFromDisk(repoRoot, filePath);
+  if (records.length === 0) return null;
+  return project(records);
+};
